package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService.Decision;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

class EntityHeatEventProofTest {
    EntityHeatDecisionJdbcLogTest h;EntityHeatEventProofService service;String id;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){h=new EntityHeatDecisionJdbcLogTest(){@Override GenerationJdbcStoreTest fixture(){return EntityHeatEventProofTest.this.fixture();}};h.setup();h.write(()->{h.save(new Decision("fictional-item","fictional-new","ready",true,1L),"new",null,"fictional-new");return true;});id=h.f.jdbc.queryForObject("SELECT id FROM jobs WHERE target_type='entity_decision'",String.class);service=new EntityHeatEventProofService(new JdbcEntityHeatEvents(h.f.source,Set.of("fictional-owner")),new DataSourceTransactionManager(h.f.source));}
    <T>T rr(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(h.f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    @Test void WholeNativeEventKeepsActualFactsWithoutCurrentEntitiesOrCommitTimeAuthority(){var value=service.find(id);assertTrue(value.hasCompleteTouchedFormat());assertEquals(1,value.snapshots().size());assertEquals(1,value.snapshots().getFirst().occurrenceCount());assertEquals(h.f.clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),value.event().actedAt());assertSame(value,rr(()->service.verifyObserved(value)));h.f.jdbc.execute("DROP TABLE analyzed_entities");assertEquals(value.event(),service.find(id).event());assertSame(value,rr(()->service.verifyObserved(value)));assertThrows(UnsupportedOperationException.class,()->value.snapshots().clear());assertFalse(value.toString().contains("Fictional"));assertNull(service.find("b".repeat(64)));}
    @Test void V1RemainsExplicitlyIncompleteAndV2NeedsReviewIsAnActualEmptyTouchedSet(){h.f.jdbc.update("DELETE FROM jobs");h.write(()->{new EntityDecisionJdbcLog(new JdbcEntityDecisions(h.f.source),"fictional-owner",h.f.clock).append("fictional-key",h.hash,new Decision("fictional-item","fictional-new","ready",true,1L),"new","fictional-item",null,"fictional-new","Fictional v1 decision");return true;});var old=service.find(id);assertFalse(old.hasCompleteTouchedFormat());assertTrue(old.snapshots().isEmpty());h.f.jdbc.update("DELETE FROM jobs");h.write(()->{h.save(new Decision("fictional-item",null,"needs_review",false,null),"needs_review",null,null);return true;});var empty=service.find(id);assertTrue(empty.hasCompleteTouchedFormat());assertEquals("needs_review",empty.operation());assertTrue(empty.snapshots().isEmpty());}
    @Test void ChangedNativeRoleAliasTimestampAndHashesCannotBecomeAnUnknownEvent(){for(String change:List.of("revision=1","operator_id='fictional-other'","state='failed'","target_type='fictional-other'","root_job_id='fictional-root'","id='"+"c".repeat(64)+"'")){setup();h.f.jdbc.update("UPDATE jobs SET "+change+" WHERE target_type='entity_decision'");assertThrows(RuntimeException.class,()->service.find(id));}setup();h.f.jdbc.update("UPDATE jobs SET created_at=? WHERE target_type='entity_decision'",LocalDateTime.ofInstant(h.f.clock.instant().plusSeconds(1),ZoneOffset.UTC));assertThrows(RuntimeException.class,()->service.find(id));setup();h.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='entity_decision'",new byte[32]);assertThrows(RuntimeException.class,()->service.find(id));}
    @Test void ValidRehashCannotChangeCountTargetOrTheOriginalPayloadContract(){var value=service.find(id);var node=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(value.event().payloadJson());((tools.jackson.databind.node.ObjectNode)node.get("entity_heat_snapshots").get(0)).put("occurrence_count",3);String raw=JdbcFrozenInputs.canonical(node);h.f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE target_type='entity_decision'",raw,JdbcGenerationLineage.hash(raw));assertThrows(RuntimeException.class,()->service.find(id));}
    @Test void PhysicalSqlBudgetsRejectBeforeLoadingOversizedEventBodies(){h.f.jdbc.update("UPDATE jobs SET action_payload=? WHERE target_type='entity_decision'","{\"fictional_wide\":\""+"F".repeat(1572865)+"\"}");assertThrows(RuntimeException.class,()->service.find(id));}
    @Test void FullObservedProofRequiresItsIssuerAndExplicitReadonlyRr(){var value=service.find(id);assertThrows(RuntimeException.class,()->service.readObserved(id));assertThrows(RuntimeException.class,()->service.verifyObserved(value));var tx=new TransactionTemplate(new DataSourceTransactionManager(h.f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->tx.execute(s->service.readObserved(id)));assertThrows(RuntimeException.class,()->h.write(()->service.readObserved(id)));var other=new EntityHeatEventProofService(new JdbcEntityHeatEvents(h.f.source,Set.of("fictional-owner")),new DataSourceTransactionManager(h.f.source));assertThrows(RuntimeException.class,()->rr(()->other.verifyObserved(value)));assertThrows(RuntimeException.class,()->rr(()->service.find(id)));}
    @Test void ColdNativeReaderAndProofServiceRequireExplicitPortsWithoutIo(){var source=mock(javax.sql.DataSource.class);var tx=mock(PlatformTransactionManager.class);new EntityHeatEventProofService(new JdbcEntityHeatEvents(source),tx);verifyNoInteractions(source,tx);assertThrows(NullPointerException.class,()->new EntityHeatEventProofService(null,tx));assertThrows(RuntimeException.class,()->new JdbcEntityHeatEvents(source,Set.of()));}
}
